actions.script:
for (let idx = 0; idx < orderCount; idx++) {
    // each order runs in its own transaction (generate#TestOrder is force-new), then clear errors
    try {
        ec.service.sync().name("mantle.order.OrderTestServices.generate#TestOrder").parameters({
                productStoreId:productStoreId, vendorPartyId:vendorPartyId, customerIdList:customerIdList,
                productIdList:productIdList, maxItems:maxItems, maxQuantity:maxQuantity, thruDate:thruDate,
                maxDaysPast:maxDaysPast}).call()
    } catch (e) {
        ec.logger.log(200, "Generate order TX error", e)
    }
    ec.message.clearErrors()
}

const shipmentMethodEnumIdList = ['ShMthGround', 'ShMthThirdDay', 'ShMthSecondDay', 'ShMthNextDay']
const salesChannelEnumIdList = ['ScWeb', 'ScWebExternal', 'ScEmail', 'ScEdi', 'ScAmazon']
const nextInt = (bound) => Math.floor(Math.random() * bound)
const pick = (list) => list[nextInt(list.length)]

// A date reaches a script as epoch millis text (UTC midnight for a Date field), or is yyyy-MM-dd text
function dateOf(value) {
    const text = String(value)
    if (/^-?\d+$/.test(text)) { const at = new Date(Number(text)); return new Date(Date.UTC(at.getUTCFullYear(), at.getUTCMonth(), at.getUTCDate())) }
    const [y, m, d] = text.slice(0, 10).split('-').map(Number)
    return new Date(Date.UTC(y, m - 1, d))
}

const customerPartyId = pick(customerIdList)
const orderDay = new Date(dateOf(thruDate).getTime() - nextInt(maxDaysPast) * 86400000)
const orderTs = ec.l10n.parseTimestamp(orderDay.toISOString().slice(0, 10) + " " + String(nextInt(12) + 8).padStart(2, '0') + ":00:00.000", 'yyyy-MM-dd HH:mm:ss.SSS')

const orderOut = ec.service.sync().name("mantle.order.OrderServices.create#Order").parameters({entryDate:orderTs,
        productStoreId:productStoreId, salesChannelEnumId:pick(salesChannelEnumIdList),
        vendorPartyId:vendorPartyId, customerPartyId:customerPartyId, carrierPartyId:'_NA_',
        shipmentMethodEnumId:pick(shipmentMethodEnumIdList)}).call()
const orderId = orderOut.orderId
const orderPartSeqId = orderOut.orderPartSeqId

ec.logger.warn(`Creating order ${orderId} date ${orderTs} customer ${customerPartyId}`)

const itemCount = nextInt(maxItems) + 1
for (let itemIdx = 0; itemIdx < itemCount; itemIdx++) {
    const productId = pick(productIdList)
    const itemQuantity = nextInt(maxQuantity)
    ec.service.sync().name("mantle.order.OrderServices.add#OrderProductQuantity").parameters({orderId:orderId,
            orderPartSeqId:orderPartSeqId, productId:productId, quantity:itemQuantity}).call()
    ec.logger.warn(`Add order ${orderId} item ${itemIdx} product ${productId} quantity ${itemQuantity}`)
}

let paymentMethodId = null, paymentInstrumentEnumId = null, shippingPostalContactMechId = null
if (customerPartyId === 'CustJqp') {
    paymentMethodId = 'CustJqpCc'
    shippingPostalContactMechId = 'CustJqpAddr'
} else {
    // find payment method or default to check instrument
    const ccPaymentMethod = ec.entity.find("mantle.account.method.PaymentMethod").condition("ownerPartyId", customerPartyId)
            .condition("paymentMethodTypeEnumId", "PmtCreditCard").one()
    if (ccPaymentMethod != null) paymentMethodId = ccPaymentMethod.paymentMethodId
    else paymentInstrumentEnumId = 'PiPersonalCheck'

    // find shipping/primary address or default to ???
    let shippingPcm = ec.entity.find("mantle.party.contact.PartyContactMech").condition("partyId", customerPartyId)
            .condition("contactMechPurposeId", "PostalShippingDest").one()
    if (shippingPcm == null) shippingPcm = ec.entity.find("mantle.party.contact.PartyContactMech")
            .condition("partyId", customerPartyId).condition("contactMechPurposeId", "PostalPrimary").one()
    if (shippingPcm != null) shippingPostalContactMechId = shippingPcm.contactMechId
}

ec.service.sync().name("mantle.order.OrderServices.set#OrderBillingShippingInfo").parameters({
        orderId:orderId, orderPartSeqId:orderPartSeqId, paymentMethodId:paymentMethodId,
        paymentInstrumentEnumId:paymentInstrumentEnumId, shippingPostalContactMechId:shippingPostalContactMechId}).call()

ec.service.sync().name("mantle.order.OrderServices.place#Order").parameters({orderId:orderId, placedDate:orderTs}).call()
ec.service.sync().name("mantle.order.OrderServices.approve#Order").parameters({orderId:orderId}).call()
ec.service.sync().name("mantle.shipment.ShipmentServices.ship#OrderPart")
        .parameters({orderId:orderId, orderPartSeqId:orderPartSeqId, shipDate:orderTs, tryAutoPackage:false}).call()
